insert into public.basketball_locations(
 slug,name,address,locality,area,region,venue_type,access_type,
 latitude,longitude,verification_status,source_label,source_url,
 last_verified_on,hours_text,notes,is_active)
select
 s.slug,s.name,s.address,s.locality,s.area,'VA',s.venue_type,s.access_type,
 null,null,'official',s.source_label,s.source_url,date '2026-10-17',s.hours_text,s.notes,true
from verified_source s
where not exists (
 select 1 from public.basketball_locations b
 where b.is_active
  and b.verification_status in ('official','provider')
  and lower(trim(b.locality))=lower(trim(s.locality))
  and regexp_replace(lower(b.name),'[^a-z0-9]','','g')=regexp_replace(lower(s.name),'[^a-z0-9]','','g')
)
on conflict (slug) do nothing;
